import threading
import uuid
import copy


class Engine:
    def __init__(self):
        self._lock = threading.Lock()
        self._tasks = {}  # task_id -> {owner, key, state, result}
        self._owner_tasks = {}  # owner -> [task_id, ...] in submission order
        self._key_tasks = {}  # (owner, key) -> task_id
        self._leases = {}  # task_id -> {worker, token, expires_at}
        self._next_task_id = 0

    def submit(self, owner, key):
        with self._lock:
            task_key = (owner, key)
            if task_key in self._key_tasks:
                task_id = self._key_tasks[task_key]
                task = self._tasks[task_id]
                if task['state'] in ('queued', 'running'):
                    return task_id
            task_id = self._next_task_id
            self._next_task_id += 1
            self._tasks[task_id] = {
                'owner': owner,
                'key': key,
                'state': 'queued',
                'result': None
            }
            self._key_tasks[task_key] = task_id
            if owner not in self._owner_tasks:
                self._owner_tasks[owner] = []
            self._owner_tasks[owner].append(task_id)
            return task_id

    def claim(self, worker, now, ttl):
        with self._lock:
            if ttl <= 0:
                return None
            eligible = []
            for task_id, task in self._tasks.items():
                if task['state'] == 'queued':
                    eligible.append(task_id)
                elif task['state'] == 'running':
                    if task_id in self._leases:
                        lease = self._leases[task_id]
                        if now >= lease['expires_at']:
                            eligible.append(task_id)
                    else:
                        eligible.append(task_id)
            if not eligible:
                return None
            task_id = eligible[0]
            task = self._tasks[task_id]
            owner = task['owner']
            token = str(uuid.uuid4())
            expires_at = now + ttl
            lease = {
                'task_id': task_id,
                'worker': worker,
                'token': token,
                'owner': owner,
                'expires_at': expires_at
            }
            self._leases[task_id] = lease
            task['state'] = 'running'
            return {
                'task_id': task_id,
                'worker': worker,
                'token': token,
                'owner': owner
            }

    def cancel(self, owner, task_id):
        with self._lock:
            if task_id not in self._tasks:
                return False
            task = self._tasks[task_id]
            if task['owner'] != owner:
                raise PermissionError(
                    f"Owner {owner} != {task['owner']}"
                )
            if task['state'] in ('completed', 'canceled'):
                return False
            task['state'] = 'canceled'
            if owner in self._owner_tasks and task_id in self._owner_tasks[owner]:
                self._owner_tasks[owner].remove(task_id)
            key = task['key']
            key_task_key = (owner, key)
            if key_task_key in self._key_tasks and self._key_tasks[key_task_key] == task_id:
                del self._key_tasks[key_task_key]
            if task_id in self._leases:
                del self._leases[task_id]
            return True

    def publish(self, lease, now, result):
        with self._lock:
            task_id = lease['task_id']
            token = lease['token']
            owner = lease['owner']
            worker = lease['worker']

            if task_id not in self._tasks:
                return False
            task = self._tasks[task_id]

            if task_id not in self._leases:
                return False
            stored_lease = self._leases[task_id]

            if stored_lease['token'] != token:
                return False

            if now >= stored_lease['expires_at']:
                return False

            if task['state'] != 'running':
                return False

            if task['owner'] != owner:
                return False

            task['state'] = 'completed'
            task['result'] = result
            del self._leases[task_id]
            return True

    def results(self, owner):
        with self._lock:
            if owner not in self._owner_tasks:
                return []
            result = []
            for task_id in self._owner_tasks[owner]:
                if task_id in self._tasks:
                    task = self._tasks[task_id]
                    if task['state'] == 'completed':
                        result.append(copy.deepcopy(task['result']))
            return result

